pec","value":{"assumption_id":"A-P1-CHOICE","scope_ref":"P1","statement":"情形(2)中"90% 信度认定次品率不超过标称值"解释为：当真实次品率 p_1 比标称值 p_0 高出一定幅度时，检验能以至少 90% 的概率正确拒收；本模型取 p_1=15% 作为备择次品率，并做敏感性分析说明 p_1 的选择对样本量的影响。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"本模型取 \(p_1=15\%\) 作为备择次品率"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-RETURN-LOOP","scope_ref":"P2","statement":"退回的不合格品拆解后，其零配件重新进入装配环节，且再次装配后的成品次品率与首次装配相同，形成可闭合的几何级数期望。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"退回的不合格品拆解后，其零配件重新进入装配环节，且再次装配后的成品次品率与首次装配相同，形成可闭合的几何级数期望"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DAG-TOPOLOGY","scope_ref":"P3","statement":"生产流程可抽象为有向无环图，不存在循环装配；拆解回流在期望意义上闭合，不改变图的拓扑结构。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"生产流程可抽象为有向无环图，不存在循环装配；拆解回流在期望意义上闭合，不改变图的拓扑结构"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BETA-PRIOR","scope_ref":"P4","statement":"次品率的先验分布取 Beta 分布，且各零配件、半成品、成品的次品率先验相互独立；先验参数取无信息的均匀先验 Beta(1,1) 或由历史批次数据估计。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"次品率的先验分布取 Beta 分布，且各零配件、半成品、成品的次品率先验相互独立；先验参数取无信息的均匀先验 \(\mathrm{Beta}(1,1)\) 或由历史批次数据估计"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLE-INDEP","scope_ref":"P4","statement":"问题 4 中用于估计各次品率的抽样检测相互独立，且抽样检测本身不改变批次内剩余产品的次品率分布。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"问题 4 中用于估计各次品率的抽样检测相互独立，且抽样检测本身不改变批次内剩余产品的次品率分布"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q1-BINOM","scope_ref":"P1","expression":"X ~ Binomial(n, p)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-X"],"rhs_symbols":["S-N1","S-P0"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"记不合格数为 \(X\sim \mathrm{Bin}(n,p)\)"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q1-CONSTRAINT","scope_ref":"P1","expression":"P(X > c | p = p_0) <= alpha AND P(X > c | p = p_1) >= 1 - beta","representation":"LATEX_PRESENTATION","lhs_symbols":["S-X","S-C1","S-P0","S-P1","S-ALPHA","S-BETA"],"rhs_symbols":[],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["E-Q1-BINOM"],"source":"MODEL","shared":false,"e1_span":"\(P(X>c\mid p=0.10)\le 0.05\) 且 \(P(X>c\mid p=0.15)\ge 0.90\)"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q2-EFFCOST","scope_ref":"P2","expression":"C_i = (b_i + t_i) / (1 - p_i) if d_i=1 else C_i = b_i","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PI","S-BI","S-TI","S-D1","S-D2"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"若检测零配件 \(i\)，则每件合格零配件的有效成本为 \((b_i+t_i)/(1-p_i)\)，不合格的直接丢弃；若不检测，则每件进入装配的零配件成本为 \(b_i\)"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q2-GEOMETRIC","scope_ref":"P2","expression":"C_total = C_0 + q*(d - V) / (1 - q)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C0","S-Q","S-D","S-V"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"总期望成本为 \(C_0 + q(d - V) + q^2(d - V) + \cdots = C_0 + \frac{q(d-V)}{1-q}\)"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q2-PROFIT","scope_ref":"P2","expression":"Pi = s - C_total","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT"],"rhs_symbols":["S-PRICE","S-C0","S-Q","S-D","S-V"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["E-Q2-GEOMETRIC","E-Q2-EFFCOST"],"source":"MODEL","shared":false,"e1_span":"期望利润（市场售价减去总期望成本）"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q3-LEAF","scope_ref":"P3","expression":"C_v = (b_v + t_v) / (1 - p_v) if d_v=1 else C_v = b_v","representation":"LATEX_PRESENTATION","lhs_symbols":["S-CV","S-BV","S-TV","S-PV","S-DV"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"对叶子节点（零配件），若检测，则 \(C_v=(b_v+t_v)/(1-p_v)\)；若不检测，则 \(C_v=b_v\)"}},{"kind":"EquationSpec","value":{"equation_id":"E-Q3-INTERNAL","scope_ref":"P3","expression":"C_v = (C_in + a_v + t_v) / (1 - p_v) if d_v=1 else C_v = C_in + a_v","representation":"LATEX_PRESENTATION","lhs_symbols":["S-CV","S-CIN","S-AV","S-TV","S-PV","S-DV"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":["E-Q3-LEAF"],"source":"MODEL","shared":false,"e1_span":"若检测，则 \(C_v=(C_{\text{in}}+a_v+t_v)/(1-p_v)\)；若不检测，则 \(C_v=C_{\text{in}}+a_v\)"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-CONSTANT-PARAMS","A-P1-CHOICE"],"variable_refs":["S-N1","S-C1","S-X"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.10},{"symbol_ref":"S-P1","value":0.15},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.10}],"equation_refs":["E-Q1-BINOM","E-Q1-CONSTRAINT"],"constraints":[],"objective":"minimize n subject to P(X>c|p=p0)<=alpha and P(X>c|p=p1)>=1-beta","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN","A-CONSTANT-PARAMS","A-RETURN-LOOP"],"variable_refs":["S-D1","S-D2","S-DF","S-DD","S-Q","S-V","S-C0","S-PROFIT"],"parameter_refs":[{"symbol_ref":"S-PI","value":0.10},{"symbol_ref":"S-BI","value":10},{"symbol_ref":"S-TI","value":2},{"symbol_ref":"S-PF","value":0.05},{"symbol_ref":"S-A","value":5},{"symbol_ref":"S-TF","value":3},{"symbol_ref":"S-R","value":20},{"symbol_ref":"S-D","value":4},{"symbol_ref":"S-PRICE","value":100}],"equation_refs":["E-Q2-EFFCOST","E-Q2-GEOMETRIC","E-Q2-PROFIT"],"constraints":[],"objective":"maximize Pi over 16 strategies","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN","A-CONSTANT-PARAMS","A-DAG-TOPOLOGY"],"variable_refs":["S-CV","S-CIN","S-DV","S-DDV","S-PROFIT3"],"parameter_refs":[{"symbol_ref":"S-PV","value":0.05},{"symbol_ref":"S-BV","value":8},{"symbol_ref":"S-TV","value":1},{"symbol_ref":"S-AV","value":3}],"equation_refs":["E-Q3-LEAF","E-Q3-INTERNAL"],"constraints":[],"objective":"maximize Pi_3 over 4096 strategies","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN","A-CONSTANT-PARAMS","A-BETA-PRIOR","A-SAMPLE-INDEP"],"variable_refs":["S-PROFIT4","S-PROFIT4_PT","S-DIFF4"],"parameter_refs":[{"symbol_ref":"S-ALPHA0","value":1},{"symbol_ref":"S-BETA0","value":1},{"symbol_ref":"S-K","value":2},{"symbol_ref":"S-N4","value":20}],"equation_refs":[],"constraints":[],"objective":"maximize posterior expected profit Pi_4","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');

// --- Binomial probability ---
function binomProb(n, k, p) {
  if (k < 0 || k > n) return 0;
  let logP = 0;
  for (let i = 1; i <= k; i++) logP += Math.log(n - k + i) - Math.log(i);
  logP += k * Math.log(p) + (n - k) * Math.log(1 - p);
  return Math.exp(logP);
}

function binomCDF(n, c, p) {
  let s = 0;
  for (let k = 0; k <= c; k++) s += binomProb(n, k, p);
  return s;
}

// --- Q1: find minimal n and c ---
function solveQ1(p0, alpha, p1, beta) {
  for (let n = 1; n <= 5000; n++) {
    for (let c = 0; c < n; c++) {
      const type1 = 1 - binomCDF(n, c, p0);
      const power = 1 - binomCDF(n, c, p1);
      if (type1 <= alpha && power >= 1 - beta) {
        return { n, c, type1, type2: 1 - power };
      }
    }
  }
  return null;
}

const q1 = solveQ1(0.10, 0.05, 0.15, 0.10);

// --- Q2: 16 strategies enumeration ---
function solveQ2(params) {
  const { p1, p2, b1, b2, t1, t2, pf, a, tf, r, d, s } = params;
  let best = { profit: -Infinity, strategy: null };
  const results = [];
  for (let d1 = 0; d1 <= 1; d1++) {
    for (let d2 = 0; d2 <= 1; d2++) {
      for (let df = 0; df <= 1; df++) {
        for (let dd = 0; dd <= 1; dd++) {
          const c1 = d1 ? (b1 + t1) / (1 - p1) : b1;
          const c2 = d2 ? (b2 + t2) / (1 - p2) : b2;
          const q1in = d1 ? 0 : p1;
          const q2in = d2 ? 0 : p2;
          const pAssemble = 1 - (1 - q1in) * (1 - q2in) * (1 - pf);
          const Cin = c1 + c2;
          let C0, qMarket;
          if (df) {
            C0 = (Cin + a + tf) / (1 - pAssemble);
            qMarket = 0;
          } else {
            C0 = Cin + a;
            qMarket = pAssemble;
          }
          let V = 0;
          if (dd) {
            V = c1 + c2;
          }
          let Ctotal;
          if (dd && qMarket > 0 && qMarket < 1) {
            Ctotal = C0 + qMarket * (d - V) / (1 - qMarket);
          } else {
            Ctotal = C0;
          }
          const profit = s - Ctotal;
          results.push({ d1, d2, df, dd, profit, Ctotal });
          if (profit > best.profit) {
            best = { profit, strategy: { d1, d2, df, dd }, Ctotal };
          }
        }
      }
    }
  }
  return { best, results };
}

const q2params = { p1: 0.10, p2: 0.10, b1: 10, b2: 10, t1: 2, t2: 2, pf: 0.05, a: 5, tf: 3, r: 20, d: 4, s: 100 };
const q2 = solveQ2(q2params);

// --- Q3: DAG enumeration (simplified 12-node DAG) ---
function solveQ3() {
  const nParts = 8, nSemi = 3, nFinal = 1;
  const totalDecisions = nParts + nSemi + nFinal;
  const totalStrategies = 1 << totalDecisions;
  let best = { profit: -Infinity, strategy: null };
  for (let mask = 0; mask < totalStrategies; mask++) {
    const detect = [];
    for (let i = 0; i < totalDecisions; i++) detect.push((mask >> i) & 1);
    const pLeaf = [0.10, 0.10, 0.10, 0.10, 0.10, 0.10, 0.10, 0.10];
    const bLeaf = [8, 8, 8, 8, 8, 8, 8, 8];
    const tLeaf = [1, 1, 1, 1, 1, 1, 1, 1];
    const C = new Array(totalDecisions).fill(0);
    const qOut = new Array(totalDecisions).fill(0);
    for (let i = 0; i < nParts; i++) {
      if (detect[i]) { C[i] = (bLeaf[i] + tLeaf[i]) / (1 - pLeaf[i]); qOut[i] = 0; }
      else { C[i] = bLeaf[i]; qOut[i] = pLeaf[i]; }
    }
    const semiInputs = [[0,1],[2,3],[4,5]];
    const pSemi = [0.05, 0.05, 0.05];
    const aSemi = [3, 3, 3];
    const tSemi = [2, 2, 2];
    for (let j = 0; j < nSemi; j++) {
      const idx = nParts + j;
      const [i1, i2] = semiInputs[j];
      const Cin = C[i1] + C[i2];
      const qIn = 1 - (1 - qOut[i1]) * (1 - qOut[i2]);
      const pAssemble = 1 - (1 - qIn) * (1 - pSemi[j]);
      if (detect[idx]) {
        C[idx] = (Cin + aSemi[j] + tSemi[j]) / (1 - pAssemble);
        qOut[idx] = 0;
      } else {
        C[idx] = Cin + aSemi[j];
        qOut[idx] = pAssemble;
      }
    }
    const finalIdx = nParts + nSemi;
    const CinF = C[nParts] + C[nParts+1] + C[nParts+2];
    const qInF = 1 - (1 - qOut[nParts]) * (1 - qOut[nParts+1]) * (1 - qOut[nParts+2]);
    const pFinal = 0.05;
    const aFinal = 5;
    const tFinal = 3;
    const pAssembleF = 1 - (1 - qInF) * (1 - pFinal);
    if (detect[finalIdx]) {
      C[finalIdx] = (CinF + aFinal + tFinal) / (1 - pAssembleF);
      qOut[finalIdx] = 0;
    } else {
      C[finalIdx] = CinF + aFinal;
      qOut[finalIdx] = pAssembleF;
    }
    const s = 200, d = 4, r = 20;
    let profit = s - C[finalIdx];
    if (qOut[finalIdx] > 0 && qOut[finalIdx] < 1) {
      const Vrecycle = C[nParts] + C[nParts+1] + C[nParts+2];
      profit = s - (C[finalIdx] + qOut[finalIdx] * (d - Vrecycle) / (1 - qOut[finalIdx]));
    }
    if (profit > best.profit) { best = { profit, strategy: detect }; }
  }
  return best;
}

const q3 = solveQ3();

// --- Q4: Bayesian re-decision ---
function betaMean(a, b) { return a / (a + b); }
function betaSecondMoment(a, b) { return a * (a + 1) / ((a + b) * (a + b + 1)); }

function solveQ4() {
  const alpha0 = 1, beta0 = 1, k = 2, n = 20;
  const alphaPost = alpha0 + k;
  const betaPost = beta0 + n - k;
  const Ep = betaMean(alphaPost, betaPost);
  const Ep2 = betaSecondMoment(alphaPost, betaPost);
  const paramsPost = { p1: Ep, p2: Ep, b1: 10, b2: 10, t1: 2, t2: 2, pf: Ep, a: 5, tf: 3, r: 20, d: 4, s: 100 };
  const q4post = solveQ2(paramsPost);
  const paramsPt = { p1: k/n, p2: k/n, b1: 10, b2: 10, t1: 2, t2: 2, pf: k/n, a: 5, tf: 3, r: 20, d: 4, s: 100 };
  const q4pt = solveQ2(paramsPt);
  return {
    posterior_profit: q4post.best.profit,
    point_estimate_profit: q4pt.best.profit,
    diff: q4post.best.profit - q4pt.best.profit,
    posterior_strategy: q4post.best.strategy,
    point_strategy: q4pt.best.strategy
  };
}

const q4 = solveQ4();

// --- Write outputs ---
fs.writeFileSync('q1_results.json', JSON.stringify(q1));
fs.writeFileSync('q2_results.json', JSON.stringify(q2));
fs.writeFileSync('q3_results.json', JSON.stringify(q3));
