  for (let i = 1; i <= k; i++) logP += Math.log(n - k + i) - Math.log(i);
  logP += k * Math.log(p) + (n - k) * Math.log(1 - p);
  return Math.exp(logP);
}

function binomTail(n, c, p) {
  let s = 0;
  for (let k = c + 1; k <= n; k++) s += binomProb(n, k, p);
  return s;
}

function solveQ1() {
  const p0 = 0.10, p1 = 0.15, alpha = 0.05, beta = 0.10;
  let bestN = null, bestC = null;
  for (let n = 1; n <= 5000; n++) {
    for (let c = 0; c < n; c++) {
      const type1 = binomTail(n, c, p0);
      const power = binomTail(n, c, p1);
      if (type1 <= alpha && power >= 1 - beta) {
        bestN = n; bestC = c;
        break;
      }
    }
    if (bestN !== null) break;
  }
  const type1Actual = binomTail(bestN, bestC, p0);
  const type2Actual = 1 - binomTail(bestN, bestC, p1);
  return { n: bestN, c: bestC, type1: type1Actual, type2: type2Actual };
}

// ========== PROBLEM 2: 16-strategy enumeration ==========
function solveQ2(params) {
  const { p1, p2, pf, b1, b2, t1, t2, tf, a, d, r, s } = params;
  let best = { profit: -Infinity, strategy: null };
  const results = [];
  for (let d1 = 0; d1 <= 1; d1++) {
    for (let d2 = 0; d2 <= 1; d2++) {
      for (let df = 0; df <= 1; df++) {
        for (let dd = 0; dd <= 1; dd++) {
          let c1, c2, defect1, defect2;
          if (d1) { c1 = (b1 + t1) / (1 - p1); defect1 = 0; }
          else { c1 = b1; defect1 = p1; }
          if (d2) { c2 = (b2 + t2) / (1 - p2); defect2 = 0; }
          else { c2 = b2; defect2 = p2; }
          const goodInput = (1 - defect1) * (1 - defect2);
          const assemCost = c1 + c2 + a;
          let effCost, marketDefect;
          if (df) {
            const goodRate = goodInput * (1 - pf);
            effCost = (assemCost + tf) / goodRate;
            marketDefect = 0;
          } else {
            effCost = assemCost;
            marketDefect = 1 - goodInput * (1 - pf);
          }
          let totalCost;
          if (dd && marketDefect > 0) {
            const V = (c1 + c2);
            totalCost = effCost + marketDefect * (d - V) / (1 - marketDefect);
          } else {
            totalCost = effCost + marketDefect * r;
          }
          const profit = s - totalCost;
          results.push({ d1, d2, df, dd, profit });
          if (profit > best.profit) best = { profit, strategy: [d1, d2, df, dd] };
        }
      }
    }
  }
  return { best, results };
}

// ========== PROBLEM 3: DAG enumeration ==========
function solveQ3(params) {
  const { leafParams, midParams, finalParams, edges } = params;
  const nLeaf = leafParams.length, nMid = midParams.length;
  const totalDecisions = nLeaf + nMid + 1 + nMid + 1;
  let best = { profit: -Infinity, strategy: null };
  const totalStrats = 1 << totalDecisions;
  for (let mask = 0; mask < totalStrats; mask++) {
    const dec = [];
    for (let b = 0; b < totalDecisions; b++) dec.push((mask >> b) & 1);
    let idx = 0;
    const leafDetect = dec.slice(idx, idx + nLeaf); idx += nLeaf;
    const midDetect = dec.slice(idx, idx + nMid); idx += nMid;
    const finalDetect = dec[idx]; idx += 1;
    const midDisasm = dec.slice(idx, idx + nMid); idx += nMid;
    const finalDisasm = dec[idx];
    const leafCost = [];
    const leafDefect = [];
    for (let i = 0; i < nLeaf; i++) {
      const { b, t, p } = leafParams[i];
      if (leafDetect[i]) { leafCost.push((b + t) / (1 - p)); leafDefect.push(0); }
      else { leafCost.push(b); leafDefect.push(p); }
    }
    const midCost = [];
    const midDefect = [];
    for (let j = 0; j < nMid; j++) {
      const { a, t, p, inputs } = midParams[j];
      let cin = 0, goodIn = 1;
      for (const inp of inputs) { cin += leafCost[inp]; goodIn *= (1 - leafDefect[inp]); }
      if (midDetect[j]) {
        midCost.push((cin + a + t) / (goodIn * (1 - p)));
        midDefect.push(0);
      } else {
        midCost.push(cin + a);
        midDefect.push(1 - goodIn * (1 - p));
      }
    }
    const { a, t, p, inputs, s, r, d } = finalParams;
    let cin = 0, goodIn = 1;
    for (const inp of inputs) { cin += midCost[inp]; goodIn *= (1 - midDefect[inp]); }
    let effCost, marketDefect;
    if (finalDetect) {
      effCost = (cin + a + t) / (goodIn * (1 - p));
      marketDefect = 0;
    } else {
      effCost = cin + a;
      marketDefect = 1 - goodIn * (1 - p);
    }
    let totalCost;
    if (finalDisasm && marketDefect > 0) {
      let V = 0;
      for (const inp of inputs) V += midCost[inp];
      totalCost = effCost + marketDefect * (d - V) / (1 - marketDefect);
    } else {
      totalCost = effCost + marketDefect * r;
    }
    const profit = s - totalCost;
    if (profit > best.profit) best = { profit, strategy: dec };
  }
  return best;
}

// ========== PROBLEM 4: Bayesian re-decision ==========
function betaMean(a, b) { return a / (a + b); }
function betaSecondMoment(a, b) { return (a * (a + 1)) / ((a + b) * (a + b + 1)); }

function solveQ4(q2params, alpha0, beta0, nSamp, kObs) {
  const alphaPost = alpha0 + kObs;
  const betaPost = beta0 + nSamp - kObs;
  const pMean = betaMean(alphaPost, betaPost);
  const p2Mean = betaSecondMoment(alphaPost, betaPost);
  const params = { ...q2params };
  params.p1 = pMean; params.p2 = pMean; params.pf = pMean;
  const q2res = solveQ2(params);
  return { posteriorMean: pMean, bestProfit: q2res.best.profit, strategy: q2res.best.strategy };
}

