,"A-SAMPLE-INDEP","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN"],"variable_refs":["S-EP","S-EP2"],"parameter_refs":[{"symbol_ref":"S-ALPHA0","value":1.0},{"symbol_ref":"S-BETA0","value":1.0},{"symbol_ref":"S-K","value":1.0},{"symbol_ref":"S-N4","value":10.0}],"equation_refs":["EQ-Q4-POSTERIOR","EQ-Q4-MOMENT1","EQ-Q4-MOMENT2"],"constraints":[],"objective":"最大化后验期望利润","dependencies":[]}}],"code":"const fs = require('fs');
function binomPmf(n, k, p) {
  if (k < 0 || k > n) return 0;
  let logp = 0;
  for (let i = 1; i <= k; i++) logp += Math.log(n - k + i) - Math.log(i);
  logp += k * Math.log(p) + (n - k) * Math.log(1 - p);
  return Math.exp(logp);
}
function binomCdf(n, c, p) {
  let s = 0;
  for (let k = 0; k <= c; k++) s += binomPmf(n, k, p);
  return s;
}
function tailProb(n, c, p) {
  return 1 - binomCdf(n, c, p);
}
// Q1: find minimal n and c
let n = 1, c = 0, found = false;
for (n = 1; n <= 10000 && !found; n++) {
  for (c = 0; c < n; c++) {
