function q2Profit(d1, d2, df, dis) {
  const p1 = 0.1, p2 = 0.1, b1 = 1.0, b2 = 1.0, t1 = 0.1, t2 = 0.1;
  const pf = 0.1, a = 1.0, tf = 0.1, r = 1.0, d = 0.1, price = 10.0;
  let c1 = d1 ? (b1 + t1) / (1 - p1) : b1;
  let c2 = d2 ? (b2 + t2) / (1 - p2) : b2;
  let q1 = d1 ? 0 : p1;
  let q2 = d2 ? 0 : p2;
  let pAssemble = 1 - (1 - q1) * (1 - q2) * (1 - pf);
  let cin = c1 + c2;
  let cost;
  if (df) {
    cost = (cin + a + tf) / (1 - pf);
  } else {
    cost = cin + a;
  }
  let q = df ? 0 : pAssemble;
  let totalCost = cost;
  if (dis && q > 0) {
    totalCost = cost + (q * d) / (1 - q);
  }
  return price - totalCost;
}
let bestProfit = -Infinity, bestStrategy = 0;
for (let s = 0; s < 16; s++) {
