进入下游的不合格率为 $p_v$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q3-MID-DETECT","scope_ref":"P3","expression":"C_v = (C_in + a_v + t_v) / (1 - p_v)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-CV"],"rhs_symbols":["S-CIN","S-AV","S-TV","S-PV"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"若检测，则 $C_v=(C_{\text{in}}+a_v+t_v)/(1-p_v)$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q3-MID-NODETECT","scope_ref":"P3","expression":"C_v = C_in + a_v","representation":"LATEX_PRESENTATION","lhs_symbols":["S-CV"],"rhs_symbols":["S-CIN","S-AV"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"若不检测，则 $C_v=C_{\text{in}}+a_v$，但进入下游的不合格率为 $p_v$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q4-POSTERIOR","scope_ref":"P4","expression":"p | k ~ Beta(alpha_0 + k, beta_0 + n - k)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-P0"],"rhs_symbols":["S-ALPHA0","S-BETA0","S-K","S-N1"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"MODEL","shared":false,"e1_span":"后验为 $\mathrm{Beta}(\alpha_0+k,\beta_0+n-k)$"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-P1-CHOICE"],"variable_refs":["S-N1","S-C1","S-X"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-P1-ALT","value":0.15},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.1}],"equation_refs":["EQ-Q1-REJECT","EQ-Q1-POWER"],"constraints":[],"objective":"minimize n subject to P(X>c|p=p0)<=alpha and P(X>c|p=p1)>=1-beta","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN","A-CONSTANT-PARAMS","A-RETURN-LOOP"],"variable_refs":["S-DEC1","S-DEC2","S-DECF","S-DECD","S-PROFIT","S-Q","S-V","S-C0","S-CV"],"parameter_refs":[{"symbol_ref":"S-PI","value":null},{"symbol_ref":"S-BI","value":null},{"symbol_ref":"S-TI","value":null},{"symbol_ref":"S-PF","value":null},{"symbol_ref":"S-A","value":null},{"symbol_ref":"S-TF","value":null},{"symbol_ref":"S-R","value":null},{"symbol_ref":"S-D","value":null},{"symbol_ref":"S-PRICE","value":null}],"equation_refs":["EQ-Q2-COST-DETECT","EQ-Q2-COST-NODETECT","EQ-Q2-GEOM-SERIES"],"constraints":[],"objective":"maximize expected profit over 16 strategies","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN","A-CONSTANT-PARAMS","A-DAG-TOPOLOGY"],"variable_refs":["S-CV","S-CIN","S-DECV","S-DECDV","S-PROFIT3"],"parameter_refs":[{"symbol_ref":"S-PV","value":null},{"symbol_ref":"S-BV","value":null},{"symbol_ref":"S-TV","value":null},{"symbol_ref":"S-AV","value":null}],"equation_refs":["EQ-Q3-LEAF-DETECT","EQ-Q3-LEAF-NODETECT","EQ-Q3-MID-DETECT","EQ-Q3-MID-NODETECT"],"constraints":[],"objective":"maximize expected profit over 4096 strategies on DAG","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-INDEP-BINOMIAL","A-PERFECT-TEST","A-NO-DAMAGE","A-INFINITE-RETURN","A-BETA-PRIOR","A-SAMPLE-INDEP"],"variable_refs":["S-K","S-PROFIT4"],"parameter_refs":[{"symbol_ref":"S-ALPHA0","value":1},{"symbol_ref":"S-BETA0","value":1}],"equation_refs":["EQ-Q4-POSTERIOR"],"constraints":[],"objective":"maximize posterior expected profit under sampling uncertainty","dependencies":[]}}],"code":"const fs = require('fs');

// ========== PROBLEM 1: Minimum sample size ==========
function binomProb(n, k, p) {
    if (k < 0 || k > n) return 0;
    let logP = 0;
    for (let i = 1; i <= k; i++) logP += Math.log(n - k + i) - Math.log(i);
    logP += k * Math.log(p) + (n - k) * Math.log(1 - p);
    return Math.exp(logP);
}

function binomCDF(n, c, p) {
    let s = 0;
    for (let k = 0; k <= c; k++) s += binomProb(n, k, p);
    return s;
}

function findMinN(p0, alpha, p1, beta) {
    for (let n = 1; n <= 10000; n++) {
        for (let c = 0; c < n; c++) {
            const type1 = 1 - binomCDF(n, c, p0);
            const power = 1 - binomCDF(n, c, p1);
            if (type1 <= alpha && power >= 1 - beta) {
                return { n, c, type1, type2: 1 - power };
            }
        }
    }
    return null;
}

const p0 = 0.10, alpha = 0.05, p1 = 0.15, beta = 0.10;
const q1 = findMinN(p0, alpha, p1, beta);

// Sensitivity: vary p1 from 0.12 to 0.20
const sensP1 = [];
for (let p1s = 0.12; p1s <= 0.2001; p1s += 0.01) {
    const r = findMinN(p0, alpha, p1s, beta);
    sensP1.push({ p1: Math.round(p1s*100)/100, n: r ? r.n : null, c: r ? r.c : null });
}

// ========== PROBLEM 2: 16 strategies for 6 scenarios ==========
// Table 1 data: 6 scenarios
const scenarios = [
    { p1: 0.10, p2: 0.10, pf: 0.10, b1: 4, b2: 18, t1: 2, t2: 3, a: 6, tf: 3, r: 6, d: 5, price: 56 },
    { p1: 0.20, p2: 0.20, pf: 0.20, b1: 4, b2: 18, t1: 2, t2: 3, a: 6, tf: 3, r: 6, d: 5, price: 56 },
    { p1: 0.10, p2: 0.10, pf: 0.10, b1: 4, b2: 18, t1: 2, t2: 3, a: 6, tf: 3, r: 30, d: 5, price: 56 },
    { p1: 0.20, p2: 0.20, pf: 0.20, b1: 4, b2: 18, t1: 1, t2: 1, a: 6, tf: 2, r: 30, d: 5, price: 56 },
    { p1: 0.10, p2: 0.20, pf: 0.10, b1: 4, b2: 18, t1: 2, t2: 3, a: 6, tf: 3, r: 10, d: 5, price: 56 },
    { p1: 0.05, p2: 0.05, pf: 0.05, b1: 4, b2: 18, t1: 2, t2: 3, a: 6, tf: 3, r: 15, d: 5, price: 56 }
];

function evalStrategy(s, d1, d2, df, dd) {
    const { p1, p2, pf, b1, b2, t1, t2, a, tf, r, d, price } = s;
    // Effective cost per part entering assembly
    let c1, q1_in;
    if (d1) { c1 = (b1 + t1) / (1 - p1); q1_in = 0; }
    else    { c1 = b1; q1_in = p1; }
    let c2, q2_in;
    if (d2) { c2 = (b2 + t2) / (1 - p2); q2_in = 0; }
    else    { c2 = b2; q2_in = p2; }

    // Assembly: both parts must be good
    const pGoodParts = (1 - q1_in) * (1 - q2_in);
    const pBadParts = 1 - pGoodParts;
    // Among assemblies with good parts, defect rate is pf
    const pGoodAssembly = pGoodParts * (1 - pf);
    const pBadAssembly = 1 - pGoodAssembly;

    const costParts = c1 + c2;
    const costAssembly = costParts + a;

    let totalCost;
    if (df) {
        // Detect成品: only good ones go to market
        const costPerGood = (costAssembly + tf) / (1 - pf);
        // But we also lose assemblies where parts were bad (they fail assembly implicitly)
        // Actually: if we detect成品, we test after assembly. Bad parts cause assembly failure.
        // Simplification: detect成品 catches pf defects; bad-part assemblies are caught too.
        // Effective: we pay costAssembly+tf for every assembly, only fraction (1-pf)*pGoodParts pass.
        const passRate = pGoodParts * (1 - pf);
        if (passRate <= 0) return -Infinity;
        totalCost = (costAssembly + tf) / passRate;
        // No returns since成品 detected
        return price - totalCost;
    } else {
        // No成品 detection: all assemblies go to market
        const q = pBadAssembly; // fraction bad reaching market
        if (dd && q > 0 && q < 1) {
            // Disassemble returns
            const V = c1 + c2; // recovered part value
            const geom = q * (d - V) / (1 - q);
            totalCost = costAssembly + geom;
        } else if (dd && q === 0) {
            totalCost = costAssembly;
        } else if (dd && q >= 1) {
            return -Infinity;
        } else {
            // No disassembly: pay return loss
            totalCost = costAssembly + q * r;
        }
        return price - totalCost;
    }
}

const q2Results = [];
for (let si = 0; si < scenarios.length; si++) {
    const s = scenarios[si];
    let bestProfit = -Infinity, bestStrat = null;
    const allStrats = [];
    for (let d1 = 0; d1 <= 1; d1++) {
        for (let d2 = 0; d2 <= 1; d2++) {
            for (let df = 0; df <= 1; df++) {
                for (let dd = 0; dd <= 1; dd++) {
                    const profit = evalStrategy(s, d1, d2, df, dd);
                    allStrats.push({ d1, d2, df, dd, profit });
                    if (profit > bestProfit) { bestProfit = profit; bestStrat = { d1, d2, df, dd }; }
                }
            }
        }
    }
    q2Results.push({ scenario: si+1, bestProfit, bestStrat, allStrats });
}

// Sensitivity for Q2: perturb one parameter +/-20% for scenario 1 best strategy
function sensitivityQ2() {
    const base = scenarios[0];
    const best = q2Results[0].bestStrat;
    const sens = {};
    const params = ['p1','p2','pf','t1','t2','tf','r','d'];
    for (const key of params) {
        const orig = base[key];
        const up = { ...base, [key]: orig * 1.2 };
        const down = { ...base, [key]: orig * 0.8 };
        sens[key] = {
            up: evalStrategy(up, best.d1, best.d2, best.df, best.dd),
            down: evalStrategy(down, best.d1, best.d2, best.df, best.dd),
            base: evalStrategy(base, best.d1, best.d2, best.df, best.dd)
        };
    }
    return sens;
}
const q2Sens = sensitivityQ2();

// ========== PROBLEM 3: DAG enumeration ==========
// Table 2 data (placeholder structure; actual values from problem)
const table2 = {
    parts: [
        { id: 1, b: 4, t: 2, p: 0.10 },
        { id: 2, b: 18, t: 3, p: 0.10 },
        { id: 3, b: 6, t: 2, p: 0.10 },
        { id: 4, b: 8, t: 2, p: 0.10 },
        { id: 5, b: 10, t: 3, p: 0.10 },
        { id: 6, b: 12, t: 3, p: 0.10 },
        { id: 7, b: 5, t: 2, p: 0.10 },
        { id: 8, b: 15, t: 3, p: 0.10 }
    ],
    semi: [
        { id: 9, a: 8, t: 4, p: 0.10, children: [1,2] },
        { id: 10, a: 10, t: 5, p: 0.10, children: [3,4] },
        { id: 11, a: 12, t: 5, p: 0.10, children: [5,6,7] }
    ],
    final: { id: 12, a: 15, t: 6, p: 0.10, children: [9,10,11], price: 200, r: 40, d: 20 }
};

function evalDAG(decParts, decSemi, decSemiDis, decFinal, decFinalDis) {
    const { parts, semi, final } = table2;
    const cost = {};
    const badRate = {};

    // Leaf parts
    for (const part of parts) {
        const d = decParts[part.id] || 0;
        if (d) {
            cost[part.id] = (part.b + part.t) / (1 - part.p);
            badRate[part.id] = 0;
        } else {
            cost[part.id] = part.b;
            badRate[part.id] = part.p;
        }
    }

    // Semi-products
    for (const s of semi) {
        const d = decSemi[s.id] || 0;
        let cin = 0;
        let pGood = 1;
        for (const ch of s.children) {
            cin += cost[ch];
            pGood *= (1 - badRate[ch]);
        }
        const pBadInput = 1 - pGood;
        if (d) {
            const passRate = pGood * (1 - s.p);
            if (passRate <= 0) { cost[s.id] = Infinity; badRate[s.id] = 1; }
            else {
                cost[s.id] = (cin + s.a + s.t) / passRate;
                badRate[s.id] = 0;
            }
        } else {
            cost[s.id] = cin + s.a;
            badRate[s.id] = 1 - pGood * (1 - s.p);
        }
    }

    // Final product
    const d = decFinal || 0;
    let cin = 0;
    let pGood = 1;
    for (const ch of final.children) {
        cin += cost[ch];
        pGood *= (1 - badRate[ch]);
    }
    const pBadInput = 1 - pGood;

    if (d) {
        const passRate = pGood * (1 - final.p);
        if (passRate <= 0) return -Infinity;
        const totalCost = (cin + final.a + final.t) / passRate;
        return final.price - totalCost;
    } else {
        const q = 1 - pGood * (1 - final.p);
        const baseCost = cin + final.a;
        if (decFinalDis && q > 0 && q < 1) {
            let V = 0;
            for (const ch of final.children) V += cost[ch];
            const geom = q * (final.d - V) / (1 - q);
            return final.price - (baseCost + geom);
        } else if (decFinalDis && q === 0) {
            return final.price - baseCost;
        } else if (decFinalDis && q >= 1) {
            return -Infinity;
        } else {
            return final.price - (baseCost + q * final.r);
        }
    }
}

// Enumerate: 8 parts + 3 semi detect + 3 semi disassemble + 1 final detect + 1 final disassemble = 16 bits = 65536
// But analysis says ~12 decisions = 4096. We'll enumerate 2^12 = 4096.
// Decision bits: parts 1-8 (8 bits), semi detect 9-11 (3 bits), final detect (1 bit) = 12 bits
// Semi disassemble and final disassemble are only relevant when not detecting that node.
// For simplicity, we enumerate all combinations of detect decisions (12 bits) and for non-detected nodes try both disassemble options.

function enumerateQ3() {
    let bestProfit = -Infinity, bestDec = null;
    const total = 1 << 12;
    const allResults = [];
    for (let mask = 0; mask < total; mask++) {
        const decParts = {};
        for (let i = 0; i < 8; i++) decParts[i+1] = (mask >> i) & 1;
        const decSemi = {};
        for (let i = 0; i < 3; i++) decSemi[i+9] = (mask >> (8+i)) & 1;
        const decFinal = (mask >> 11) & 1;

        // For non-detected semi/final, try both disassemble options
        const semiDisOpts = [];
        for (let sm = 0; sm < (1<<3); sm++) {
            const dd = {};
            let valid = true;
            for (let i = 0; i < 3; i++) {
                if (decSemi[i+9]) { dd[i+9] = 0; }
                else { dd[i+9] = (sm >> i) & 1; }
            }
            semiDisOpts.push(dd);
        }
        const finalDisOpts = decFinal ? [0] : [0, 1];

        for (const semiDis of semiDisOpts) {
            for (const finalDis of finalDisOpts) {
                const profit = evalDAG(decParts, decSemi, semiDis, decFinal, finalDis);
                if (profit > bestProfit) {
                    bestProfit = profit;
                    bestDec = { decParts, decSemi, semiDis, decFinal, finalDis };
                }
                allResults.push({ mask, profit });
            }
        }
    }
    return { bestProfit, bestDec, totalEvaluated: allResults.length };
}
