// ========== PROBLEM 4: Bayesian re-decision ==========
function betaMean(a, b) { return a / (a + b); }
function betaSecondMoment(a, b) { return (a * (a + 1)) / ((a + b) * (a + b + 1)); }

function posteriorParams(alpha0, beta0, n, k) {
    return { alpha: alpha0 + k, beta: beta0 + n - k };
}

// For Q4, we use the Q1 sample results to update defect rates, then re-evaluate Q2 strategies
function q4ReEvaluate(scenarioIdx, n, k1, k2, kf) {
    const s = scenarios[scenarioIdx];
    const alpha0 = 1, beta0 = 1;
    const post1 = posteriorParams(alpha0, beta0, n, k1);
    const post2 = posteriorParams(alpha0, beta0, n, k2);
    const postf = posteriorParams(alpha0, beta0, n, kf);

    const Ep1 = betaMean(post1.alpha, post1.beta);
    const Ep2 = betaMean(post2.alpha, post2.beta);
    const Epf = betaMean(postf.alpha, postf.beta);

    // Use posterior means as plug-in estimates for strategy evaluation
    const sPost = { ...s, p1: Ep1, p2: Ep2, pf: Epf };

    let bestProfit = -Infinity, bestStrat = null;
    for (let d1 = 0; d1 <= 1; d1++) {
        for (let d2 = 0; d2 <= 1; d2++) {
            for (let df = 0; df <= 1; df++) {
                for (let dd = 0; dd <= 1; dd++) {
                    const profit = evalStrategy(sPost, d1, d2, df, dd);
                    if (profit > bestProfit) { bestProfit = profit; bestStrat = { d1, d2, df, dd }; }
                }
            }
        }
    }
    return { bestProfit, bestStrat, Ep1, Ep2, Epf };
}

